import fitz
from openai import OpenAI
from dotenv import load_dotenv
import os, json

load_dotenv()
client = OpenAI(api_key=os.getenv('OPENAI_API_KEY'))

def analyse_contract(pdf_path):
    pdf = fitz.open(pdf_path)
    text = ''.join(page.get_text() for page in pdf)[:6000]
    r = client.chat.completions.create(
        model='gpt-4o-mini',
        messages=[
            {'role':'system','content':'Analyse this contract. Return JSON: {"parties": [string], "start_date": string, "end_date": string, "key_obligations": [string], "termination_clauses": [string], "red_flags": [string]}'},
            {'role':'user','content':text}
        ]
    )
    return json.loads(r.choices[0].message.content)

result = analyse_contract('contract.pdf')
for key, val in result.items():
    print(f'\n{key.upper()}:')
    if isinstance(val, list):
        for item in val: print(f'  • {item}')
    else:
        print(f'  {val}')

